if (!process.env.MARKDOWN) throw new Error('missing markdown');
const fs = require('fs');
const os = require('os');
const path = require('path');
const tmpDir = os.tmpdir();
const mdPath = path.join(tmpDir, `input-${Date.now()}.md`);
fs.writeFileSync(mdPath, process.env.MARKDOWN);
ready = { mdPath, tmpDir };

const { execSync } = require('child_process');
const outPath = path.join(ready.tmpDir, `output-${Date.now()}.pdf`);
execSync(`npx markdown-pdf "${ready.mdPath}" -o "${outPath}"`);
result = { pdf_path: outPath };
